mapper.select:
SELECT CAST(c.id AS CHAR) AS id, c.cust_no, c.cust_name, c.unified_credit_code, c.legal_representative, c.registered_capital, c.registered_address, c.business_address, c.business_scope, c.contact_person, c.contact_mobile, c.industry, c.group_type, c.group_name, c.customer_type, c.enterprise_type, c.is_keystone, c.is_account_opened, c.touch_restricted, c.customer_desc, c.credit_amount, c.credit_exposure_amount, l.entry_org_id AS owner_org_id, l.lead_no, l.lead_type, CAST(l.id AS CHAR) AS lead_id, CAST(l.id AS CHAR) AS source_lead_id, CAST(c.current_lead_id AS CHAR) AS current_lead_id, c.main_manager_id, c.main_org_id, c.ownership_status, c.last_touch_time, l.distribution_mode, l.pool_status, '全行客户经理' AS claim_scope, (SELECT COUNT(*) FROM MARKETING_CUSTOMER_CLAIM claim_count WHERE claim_count.source_lead_id = l.id AND claim_count.claim_status = 'CLAIMED') AS claimed_count, l.entry_time AS released_time, c.record_status AS status, c.created_time, c.updated_time FROM MARKETING_LEAD_INFO l JOIN MARKETING_CUSTOMER_INFO c ON c.id = l.cust_id AND c.record_status = 'ACTIVE' WHERE l.record_status = 'ACTIVE' AND l.lead_status = 'APPROVED' AND l.distribution_mode = 'PUBLIC' AND l.pool_status = 'AVAILABLE' AND c.ownership_status = 'UNASSIGNED' AND c.main_manager_id IS NULL AND NOT EXISTS ( SELECT 1 FROM MARKETING_CUSTOMER_CLAIM cc WHERE cc.source_lead_id = l.id AND cc.claimed_by = #{empId} AND cc.claim_status = 'CLAIMED' )
AND (c.cust_name LIKE CONCAT('%', #{keyword}, '%') OR c.cust_no LIKE CONCAT('%', #{keyword}, '%') OR c.unified_credit_code LIKE CONCAT('%', #{keyword}, '%') OR l.lead_no LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY l.updated_time DESC, l.id DESC LIMIT #{offset}, #{limit}

SELECT requested.org_code, COALESCE(customer_stats.valid_customer_count, 0) AS valid_customer_count, COALESCE(task_stats.pending_follow_up_task_count, 0) AS pending_follow_up_task_count, COALESCE( GREATEST(customer_stats.source_updated_at, task_stats.source_updated_at), customer_stats.source_updated_at, task_stats.source_updated_at ) AS source_updated_at FROM (
SELECT #{orgCode} AS org_code
) requested LEFT JOIN ( SELECT c.main_org_id AS org_code, COUNT(DISTINCT c.id) AS valid_customer_count, MAX(COALESCE(c.updated_time, c.created_time)) AS source_updated_at FROM MARKETING_CUSTOMER_INFO c WHERE c.record_status = 'ACTIVE' AND c.ownership_status = 'ASSIGNED' AND c.main_org_id IS NOT NULL AND c.main_org_id IN
#{orgCode}
GROUP BY c.main_org_id ) customer_stats ON customer_stats.org_code = requested.org_code LEFT JOIN ( SELECT t.org_id AS org_code, COUNT(DISTINCT t.id) AS pending_follow_up_task_count, MAX(COALESCE( GREATEST( COALESCE(t.updated_time, t.created_time), COALESCE(c.updated_time, c.created_time) ), COALESCE(t.updated_time, t.created_time), COALESCE(c.updated_time, c.created_time) )) AS source_updated_at FROM MARKETING_TOUCH_TASK t JOIN MARKETING_CUSTOMER_INFO c ON c.id = t.cust_id AND c.record_status = 'ACTIVE' AND c.ownership_status = 'ASSIGNED' AND c.main_org_id = t.org_id WHERE t.task_type = 'FIRST_TOUCH' AND t.task_status IN ('PENDING', 'IN_PROGRESS') AND t.cancel_time IS NULL AND t.org_id IS NOT NULL AND t.org_id IN
#{orgCode}
GROUP BY t.org_id ) task_stats ON task_stats.org_code = requested.org_code
